examples.template:
if (!open) MonarchButton(text = {{trigger}}, onClick = { open = true })
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = "Help & support") {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
            MonarchTabs(selectedIndex = currentTab, onSelectedIndexChange = { currentTab = it }) {
                tab("Chat")
                tab("Help")
            }
            if (currentTab == 0) {
                MonarchText(text = {{chat.system}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                MonarchMessageRow(
                    author = MonarchMessageRowAuthor({{chat.agent}}),
                    time = {{chat.at|millis}},
                    timeStyle = MonarchMessageRowTimeStyle.Clock,
                ) {
                    MonarchText({{chat.text}})
                }
                MonarchText(text = {{chat.expectedReply}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                sent.forEach { text ->
                    MonarchMessageRow(
                        author = MonarchMessageRowAuthor("You"),
                        time = 1_794_614_460_000L,
                        timeStyle = MonarchMessageRowTimeStyle.Clock,
                    ) {
                        MonarchText(text)
                    }
                }
                MonarchMessageComposer(
                    label = "Message",
                    state = draft,
                    onSend = { message -> sent = sent + message.text /* Post it to the support chat API. */ },
                    placeholder = "Write a message…",
                )
            } else {
                MonarchSearchResults(
                    groups = articles,
                    onSelect = { result, _ -> /* Open result.id in the help center. */ },
                    modifier = Modifier.heightIn(max = MonarchTheme.spacing.space24 * 2),
                )
                MonarchText(text = "Other ways to reach us", style = MonarchTextStyle.Subheading)
                MonarchText(text = {{contact.description}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                MonarchLink(
                    text = {{contact.label}},
                    onClick = { /* Start an ACTION_SENDTO intent with a mailto: address. */ },
                    variant = MonarchLinkVariant.Standalone,
                )
            }
            // The footer shows on both tabs, as the web's does.
            Row(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchBadge(text = "System status: " + {{status}}, tone = MonarchTone.Success)
                MonarchLink(
                    text = "Help Center",
                    onClick = { /* Open the help center in a Custom Tab. */ },
                    external = true,
                )
            }
        }
    }
}

