    MonarchSearchResultGroup(
        title = "Popular articles",
        id = "popular",
        results = listOf(
            MonarchSearchResult(title = {{articles.0}}, id = "a1"),
            MonarchSearchResult(title = {{articles.1}}, id = "a2"),
            MonarchSearchResult(title = {{articles.2}}, id = "a3"),
        ),
    ),
)

